const override = $('Test Input Override').first().json || {};
const classRows = $input.all().map((item) => item.json || {}).filter((row) => row.id);
const snapshotDate = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
return [{
  json: {
    class_ids: classRows.map((row) => row.id),
    class_rows: classRows,
    snapshot_date: snapshotDate,
    override,
  },
}];

const prepared = $('Prepare Climate Snapshot Batch').first().json || {};
const override = prepared.override || {};
const classRows = Array.isArray(prepared.class_rows) ? prepared.class_rows : [];
const classMap = new Map(classRows.map((row) => [row.id, row]));
const snapshot = $json || {};
const resolvedClassId = override.class_id || snapshot.class_id || null;
const classMeta = classMap.get(resolvedClassId) || {};
const avgMood = override.avg_mood_score ?? snapshot.avg_mood_score ?? null;
const avgPace = override.avg_pace_score ?? snapshot.avg_pace_score ?? null;
const avgFairness = override.avg_fairness_score ?? snapshot.avg_fairness_score ?? null;
const totalResponses = Number(override.total_responses ?? snapshot.total_responses ?? 0);
const safeFromSnapshot = snapshot.k_anonymity_safe === true || avgMood !== null;
const safe = override.k_anonymity_safe === true || (override.k_anonymity_safe !== false && safeFromSnapshot);
return {
  json: {
    class_id: resolvedClassId || classMeta.id || null,
    class_name: override.class_name || classMeta.name || null,
    teacher_id: override.teacher_id || classMeta.teacher_id || null,
    avg_mood_score: avgMood,
    avg_pace_score: avgPace,
    avg_fairness_score: avgFairness,
    total_responses: totalResponses,
    k_anonymity_safe: safe,
    blocked_reason: override.blocked_reason || snapshot.blocked_reason || (safe ? null : totalResponses > 0 ? 'k_anonymity' : 'no_responses'),
    snapshot_date: snapshot.snapshot_date || prepared.snapshot_date || null,
    sentiment_distribution: override.sentiment_distribution || {},
    raw_comments: override.raw_comments || [],
    test_force_low_confidence: override.test_force_low_confidence === true,
    test_force_invalid_ai_json: override.test_force_invalid_ai_json === true,
    test_force_valid_ai_output: override.test_force_valid_ai_output === true,
    test_label: override.test_label || null,
    source: override.source || 'manual_test_override',
    scenario: override.scenario || null,
  },
};

const item = $json || {};
const blockedReason = item.blocked_reason || 'k_anonymity';
return {
  json: {
    ...item,
    blocked_reason: blockedReason,
    decision_path_json: {
      route: 'blocked_by_k_anonymity',
      blocked_reason: blockedReason,
      snapshot_date: item.snapshot_date || null,
    },
  },
};

let metrics = {};
try { metrics = $('Tool: Get Teacher Metrics').item.json || {}; } catch(e){}
let summary = {};
try { summary = $("Call 'Tool: Get Past Recommendations'").item.json || {}; } catch(e){}
let climate = {};
try { climate = $('Get Aggregated Climate Data').item.json || {}; } catch(e){}

let avg_mood = (metrics.avg_mood_score !== undefined && metrics.avg_mood_score !== null)
  ? metrics.avg_mood_score
  : (climate.avg_mood_score !== undefined && climate.avg_mood_score !== null)
    ? climate.avg_mood_score
    : $input.item.json.avg_mood_score;

return {
  json: {
    ...climate,
    ...$input.item.json,
    teacher_metrics: metrics,
    past_summary: summary,
    avg_mood_score: avg_mood
  }
};

